import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Item — 24 variants
 *   Type   Default (transparent) | Outline (1px border) | Muted (`muted` fill)
 *   State  Default | Hover
 *   Size   Default (py 10, px 12) | Extra small (py 8, px 10)
 *   Dir    LTR | RTL
 * Plus ItemHeader and a LeadingVisual set (Type = Avatar | Icon).
 */
const itemVariants = cva(
  cn(
    "group/item flex flex-wrap items-center gap-2.5 rounded-lg text-sm transition-colors outline-none",
    "focus-visible:border-ring focus-visible:ring-ring-subtle focus-visible:ring-[3px]",
    "[a&]:hover:bg-accent [a&]:transition-colors"
  ),
  {
    variants: {
      variant: {
        default: "bg-transparent hover:bg-accent",
        outline: "border border-border bg-transparent hover:bg-accent",
        muted: "bg-muted",
      },
      size: {
        default: "px-3 py-2.5",
        sm: "px-3 py-2",
        xs: "px-2.5 py-2 text-xs",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
);

function Item({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof itemVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "div";
  return (
    <Comp
      data-slot="item"
      data-variant={variant}
      data-size={size}
      className={cn(itemVariants({ variant, size }), className)}
      {...props}
    />
  );
}

function ItemGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      role="list"
      data-slot="item-group"
      className={cn("group/item-group flex flex-col", className)}
      {...props}
    />
  );
}

/** figma: LeadingVisual — Type = Avatar | Icon. */
function ItemMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & { variant?: "default" | "icon" | "avatar" | "image" }) {
  return (
    <div
      data-slot="item-media"
      data-variant={variant}
      className={cn(
        "flex shrink-0 items-center justify-center gap-2 self-start [&_svg]:pointer-events-none",
        variant === "icon" &&
          "size-8 rounded-md border bg-muted [&_svg:not([class*='size-'])]:size-4",
        variant === "avatar" && "size-8 shrink-0",
        variant === "image" && "size-10 overflow-hidden rounded-md [&_img]:size-full [&_img]:object-cover",
        className
      )}
      {...props}
    />
  );
}

function ItemContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-content"
      className={cn("flex flex-1 flex-col gap-0.5 [&+[data-slot=item-content]]:flex-none", className)}
      {...props}
    />
  );
}

function ItemTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-title"
      className={cn("flex w-fit items-center gap-2 text-sm leading-snug font-medium", className)}
      {...props}
    />
  );
}

function ItemDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="item-description"
      className={cn("line-clamp-2 text-sm leading-normal font-normal text-muted-foreground", className)}
      {...props}
    />
  );
}

function ItemActions({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-slot="item-actions" className={cn("flex items-center gap-1.5", className)} {...props} />
  );
}

/** figma: ItemHeader. */
function ItemHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-header"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  );
}

function ItemFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-footer"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  );
}

function ItemSeparator({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      role="separator"
      data-slot="item-separator"
      className={cn("my-0 h-px w-full bg-border", className)}
      {...props}
    />
  );
}

export {
  Item,
  ItemGroup,
  ItemMedia,
  ItemContent,
  ItemTitle,
  ItemDescription,
  ItemActions,
  ItemHeader,
  ItemFooter,
  ItemSeparator,
  itemVariants,
};
